import{_ as r,a0 as i,w as l,s as u,I as o,x as n,a1 as s,A as d,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 有問必答：如何在 Linux 上安裝 Node.js | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在 Linux 上安裝 Node.js | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在 Linux 上安裝 Node.js | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在 Linux 上安裝 Node.js | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20151116 Linux FAQs with Answers--How to install Node.js on Linux","title":"Linux 有問必答：如何在 Linux 上安裝 Node.js","tag":"201603","desc":""},"relativePath":"201603/20151116 Linux FAQs with Answers--How to install Node.js on Linux.md","filePath":"[post].md"}'),p={name:"201603/20151116 Linux FAQs with Answers--How to install Node.js on Linux.md"};function j(x,e,m,N,L,f){const t=i("Link");return l(),u("div",null,[e[20]||(e[20]=o("h1",{id:"linux-有問必答-如何在-linux-上安裝-node-js",tabindex:"-1"},[n("Linux 有問必答：如何在 Linux 上安裝 Node.js "),o("a",{class:"header-anchor",href:"#linux-有問必答-如何在-linux-上安裝-node-js","aria-label":"Permalink to “Linux 有問必答：如何在 Linux 上安裝 Node.js”"},"​")],-1)),e[21]||(e[21]=o("blockquote",null,[o("p",null,[o("strong",null,"問題"),n(": 如何在你的 Linux 發行版上安裝 Node.js？")])],-1)),o("p",null,[s(t,{href:"http://nodejs.org/"},{default:d(()=>[...e[0]||(e[0]=[n("Node.js",-1)])]),_:1}),e[2]||(e[2]=n(" 是建立在谷歌的 V8 JavaScript 引擎服務器端的軟件平台上。在構建高性能的服務器端應用程序上，Node.js 在 JavaScript 中已是首選方案。是什麼讓使用 Node.js 庫和應用程序的",-1)),s(t,{href:"https://www.npmjs.com/"},{default:d(()=>[...e[1]||(e[1]=[n("龐大生態系統",-1)])]),_:1}),e[3]||(e[3]=n("來開發服務器後台變得如此流行。Node.js 自帶一個被稱為 npm 的命令列工具可以讓你輕鬆地安裝它，進行版本控制並使用 npm 的在線倉庫來管理 Node.js 庫和應用程序的依賴關係。",-1))]),e[22]||(e[22]=a(`<p>在本教程中，我將介紹 <strong>如何在主流 Linux 發行版上安裝 Node.js，包括 Debian，Ubuntu，Fedora 和 CentOS</strong> 。</p><p>Node.js 在一些發行版上有預構建的程序包（如，Fedora 或 Ubuntu），而在其他發行版上你需要通過源碼安裝。由於 Node.js 發展比較快，建議從源碼安裝最新版而不是安裝一個過時的預構建的程序包。最新的 Node.js 自帶 npm（Node.js 的包管理器），讓你可以輕鬆的安裝 Node.js 的外部模組。</p><h3 id="在-debian-上安裝-node-js-on" tabindex="-1">在 Debian 上安裝 Node.js on <a class="header-anchor" href="#在-debian-上安裝-node-js-on" aria-label="Permalink to “在 Debian 上安裝 Node.js on”">​</a></h3><p>從 Debian 8 (Jessie)開始，Node.js 已被納入官方軟​​件倉庫。因此，你可以使用如下方式安裝它：</p><pre><code>$ sudo apt-get install npm
</code></pre><p>在 Debian 7 (Wheezy) 以前的版本中,你需要使用下面的方式來源碼安裝：</p><pre><code>$ sudo apt-get install python g++ make
$ wget http://nodejs.org/dist/node-latest.tar.gz
$ tar xvfvz node-latest.tar.gz
$ cd node-v0.10.21 (replace a version with your own)
$ ./configure
$ make
$ sudo make install
</code></pre><h3 id="在-ubuntu-或-linux-mint-中安裝-node-js" tabindex="-1">在 Ubuntu 或 Linux Mint 中安裝 Node.js <a class="header-anchor" href="#在-ubuntu-或-linux-mint-中安裝-node-js" aria-label="Permalink to “在 Ubuntu 或 Linux Mint 中安裝 Node.js”">​</a></h3><p>Node.js 被包含在 Ubuntu（13.04 及更高版本）。因此，安裝非常簡單。以下方式將安裝 Node.js 和 npm。</p><pre><code>$ sudo apt-get install npm
$ sudo ln -s /usr/bin/nodejs /usr/bin/node
</code></pre>`,10)),o("p",null,[e[5]||(e[5]=n("而 Ubuntu 中的 Node.js 可能版本比較老，你可以從 ",-1)),s(t,{href:"https://launchpad.net/~chris-lea/+archive/node.js"},{default:d(()=>[...e[4]||(e[4]=[n("其 PPA",-1)])]),_:1}),e[6]||(e[6]=n(" 中安裝最新的版本。",-1))]),e[23]||(e[23]=a(`<pre><code>$ sudo apt-get install python-software-properties python g++ make
$ sudo add-apt-repository -y ppa:chris-lea/node.js
$ sudo apt-get update
$ sudo apt-get install npm
</code></pre><h3 id="在-fedora-中安裝-node-js" tabindex="-1">在 Fedora 中安裝 Node.js <a class="header-anchor" href="#在-fedora-中安裝-node-js" aria-label="Permalink to “在 Fedora 中安裝 Node.js”">​</a></h3><p>Node.js 被包含在 Fedora 的 base 倉庫中。因此，你可以在 Fedora 中用 yum 安裝 Node.js。</p><pre><code>$ sudo yum install npm
</code></pre><p>如果你想安裝 Node.js 的最新版本，可以按照以下步驟使用源碼來安裝。</p><pre><code>$ sudo yum groupinstall &#39;Development Tools&#39;
$ wget http://nodejs.org/dist/node-latest.tar.gz
$ tar xvfvz node-latest.tar.gz
$ cd node-v0.10.21 (replace a version with your own)
$ ./configure
$ make
$ sudo make install
</code></pre><h3 id="在-centos-或-rhel-中安裝-node-js" tabindex="-1">在 CentOS 或 RHEL 中安裝 Node.js <a class="header-anchor" href="#在-centos-或-rhel-中安裝-node-js" aria-label="Permalink to “在 CentOS 或 RHEL 中安裝 Node.js”">​</a></h3><p>在 CentOS 使用 yum 包管理器來安裝 Node.js，首先啓用 EPEL 軟件庫，然後運行：</p><pre><code>$ sudo yum install npm
</code></pre><p>如果你想在 CentOS 中安裝最新版的 Node.js，其安裝步驟和在 Fedora 中的相同。</p><h3 id="在-arch-linux-上安裝-node-js" tabindex="-1">在 Arch Linux 上安裝 Node.js <a class="header-anchor" href="#在-arch-linux-上安裝-node-js" aria-label="Permalink to “在 Arch Linux 上安裝 Node.js”">​</a></h3><p>Node.js 在 Arch Linux 的社區庫中可以找到。所以安裝很簡單，只要運行：</p><pre><code>$ sudo pacman -S nodejs npm
</code></pre><h3 id="檢查-node-js-的版本" tabindex="-1">檢查 Node.js 的版本 <a class="header-anchor" href="#檢查-node-js-的版本" aria-label="Permalink to “檢查 Node.js 的版本”">​</a></h3><p>一旦你已經安裝了 Node.js，你可以使用如下所示的方法檢查 Node.js 的版本。</p><pre><code>$ node --version 
</code></pre><hr>`,17)),o("p",null,[e[8]||(e[8]=n("via: ",-1)),s(t,{href:"http://ask.xmodulo.com/install-node-js-linux.html"},{default:d(()=>[...e[7]||(e[7]=[n("http://ask.xmodulo.com/install-node-js-linux.html",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=n("作者：",-1)),s(t,{href:"http://ask.xmodulo.com/author/nanni"},{default:d(()=>[...e[9]||(e[9]=[n("Dan Nanni",-1)])]),_:1}),e[13]||(e[13]=n(" 譯者：",-1)),s(t,{href:"https://github.com/strugglingyou"},{default:d(()=>[...e[10]||(e[10]=[n("strugglingyou",-1)])]),_:1}),e[14]||(e[14]=n(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:d(()=>[...e[11]||(e[11]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=n("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[15]||(e[15]=[n("LCTT",-1)])]),_:1}),e[18]||(e[18]=n(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:d(()=>[...e[16]||(e[16]=[n("Linux中國",-1)])]),_:1}),e[19]||(e[19]=n(" 榮譽推出",-1))])])}const T=r(p,[["render",j]]);export{b as __pageData,T as default};
